  &reftitle.examples;

   Ejemplo de Yaf_Response_Abstract::__construct


<?php
/* habitualmente no hace falta construir una respuesta a mano:
 * el despachador crea una y la proporciona */
$response = Yaf_Dispatcher::getInstance()->getResponse();

/* construirla directamente resulta útil sobre todo en pruebas */
$response = new Yaf_Response_Http();
$response->setBody("Hello World");

echo $response;
?>


   &example.outputs.similar;


Hello World
